1	#!/usr/bin/env node
2	/**
3	 * doctrine59-probe.mjs — FROZEN counter for kumitate round 59, claim C2 (rule D59).
4	 *
5	 *   node .ufo/waves/round-59/probe/doctrine59-probe.mjs <lane> <rev>
6	 *
7	 * Predicate DOCTRINE59_HELD, byte-identical with plan.md §Claims and the report:
8	 * DOCTRINE59_HELD — node .ufo/waves/round-59/probe/doctrine59-probe.mjs /home/vgpnk/Projects/shokunin/kumitate-shokunin <rev> prints "DOCTRINE59: DOCTRINE59_HELD held=5/5 checks=5 rev=<rev> rule=D59" and exits 0.
9	 *
10	 * Five checks over the committed bytes of <rev> (git archive, never the worktree):
11	 *   E1  corpus/knowledge/mcp-orchestration-contract.md exists; its first line
12	 *       cites S125, S127 and S136 and contains modelcontextprotocol.io; the
13	 *       first five lines contain verified-at: 2026-10-24 and recheck:.
14	 *   E2  at least 8 lines starting with "- " each carry
15	 *       receipt:<path>@sha256:<64hex>, the paths are distinct, and each path
16	 *       exists at rev with that sha256.
17	 *   E3  corpus/SOURCES.md has rows S125, S127 and S136 with status mined and
18	 *       a used-by cell naming corpus/knowledge/mcp-orchestration-contract.md;
19	 *       .ufo/pins/source-captures.json pins all three and each capture blob
20	 *       matches its pinned sha256.
21	 *   E4  corpus/lessons/round-59.md contains
22	 *       `ADMIT mcp-orchestration-contract.md`,
23	 *       `REJECT durable-execution-and-fanout-primitives-2026-10-24.md` and
24	 *       `REJECT durable-execution-failure-detection.md`, and the word `flip:`
25	 *       occurs at least twice.
26	 *   E5  .ufo/waves/round-59/assimilation/collisions exists and has zero
27	 *       non-empty lines; reg-ids contains S124 and does not contain S125;
28	 *       staged-ids contains S125.
29	 *
30	 * Frozen before any data seat scored. A live census is not a check: it already
31	 * exits 0 at the base (the R58-V1 class — a check that passes before the work
32	 * must not be reported as 0).
33	 */
34	import { spawnSync } from 'node:child_process';
35	import { createHash } from 'node:crypto';
36	import { existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
37	import { tmpdir } from 'node:os';
38	import { join, resolve } from 'node:path';
39	
40	const RULE = 'D59';
41	const EXPECTED_CHECKS = 5;
42	const ENTRY = 'corpus/knowledge/mcp-orchestration-contract.md';
43	
44	const [laneArg, rev, ...rest] = process.argv.slice(2);
45	if (!laneArg || !rev || rest.length) {
46	  process.stderr.write('DOCTRINE59: USAGE node doctrine59-probe.mjs <lane> <rev>\n');
47	  process.exit(64);
48	}
49	const lane = resolve(laneArg);
50	if (!existsSync(join(lane, '.git'))) {
51	  process.stderr.write(`DOCTRINE59: USAGE ${JSON.stringify(lane)} is not a git repo\n`);
52	  process.exit(64);
53	}
54	if (!/^[0-9a-f]{7,64}$/.test(rev)) {
55	  process.stderr.write('DOCTRINE59: USAGE <rev> must be a lowercase hex object name\n');
56	  process.exit(64);
57	}
58	const sha = (b) => createHash('sha256').update(b).digest('hex');
59	const checks = [];
60	const hold = (id, ok, detail) => checks.push({ id, ok, detail });
61	const T = mkdtempSync(join(tmpdir(), 'd59-probe.'));
62	
63	function finish(code, line) {
64	  rmSync(T, { recursive: true, force: true });
65	  process.stdout.write(line + '\n');
66	  for (const c of checks) process.stdout.write(` | ${c.id} ${c.ok ? 'PASS' : 'MISS'} ${c.detail}`);
67	  if (checks.length) process.stdout.write('\n');
68	  process.exit(code);
69	}
70	
71	try {
72	  const tar = spawnSync('bash', ['-lc',
73	    `git -C ${JSON.stringify(lane)} archive ${JSON.stringify(rev)} | tar -x -C ${JSON.stringify(T)}`],
74	    { encoding: 'utf8', timeout: 180000 });
75	  if (tar.status !== 0) {
76	    process.stderr.write(`DOCTRINE59: FAIL-CLOSED rev unreadable (${tar.status})\n`);
77	    rmSync(T, { recursive: true, force: true });
78	    process.exit(2);
79	  }
80	  const readT = (p) => { try { return readFileSync(join(T, p)); } catch { return null; } };
81	  const text = (p) => { const b = readT(p); return b ? b.toString('utf8') : null; };
82	
83	  {
84	    const entry = text(ENTRY);
85	    if (!entry) hold('E1', false, 'entry-absent');
86	    else {
87	      const lines = entry.split('\n');
88	      const head = lines.slice(0, 5).join('\n');
89	      const ok = /S125/.test(lines[0] || '') && /S127/.test(lines[0] || '') && /S136/.test(lines[0] || '')
90	        && /modelcontextprotocol\.io/.test(lines[0] || '')
91	        && /verified-at:\s*2026-10-24/.test(head) && /recheck:/.test(head);
92	      hold('E1', ok, ok ? 'trio' : 'header-miss');
93	    }
94	  }
95	  {
96	    const entry = text(ENTRY) || '';
97	    const clauses = entry.split('\n').filter((l) => l.startsWith('- ') && /receipt:.+@sha256:[0-9a-f]{64}/.test(l));
98	    const paths = [];
99	    let hashMiss = 0;
100	    for (const line of clauses) {
101	      const m = line.match(/receipt:([^@\s]+)@sha256:([0-9a-f]{64})/);
102	      if (!m) { hashMiss += 1; continue; }
103	      paths.push(m[1]);
104	      const blob = readT(m[1]);
105	      if (!blob || sha(blob) !== m[2]) hashMiss += 1;
106	    }
107	    const distinct = new Set(paths).size === paths.length && paths.length >= 8;
108	    const ok = clauses.length >= 8 && distinct && hashMiss === 0;
109	    hold('E2', ok, `clauses=${clauses.length} distinct=${new Set(paths).size} hash-miss=${hashMiss}`);
110	  }
111	  {
112	    const sources = text('corpus/SOURCES.md') || '';
113	    const pins = text('.ufo/pins/source-captures.json');
114	    let pinDoc = null;
115	    try { pinDoc = pins ? JSON.parse(pins) : null; } catch { pinDoc = null; }
116	    const want = ['S125', 'S127', 'S136'];
117	    let rowOk = true;
118	    const why = [];
119	    for (const id of want) {
120	      const row = sources.split('\n').find((l) => new RegExp(`^ {0,3}\\|\\s*${id}\\s*\\|`).test(l));
121	      if (!row) { rowOk = false; why.push(`${id}:missing`); continue; }
122	      const cells = row.split('|').slice(1, -1).map((c) => c.trim());
123	      if (cells.length !== 11) { rowOk = false; why.push(`${id}:cols=${cells.length}`); }
124	      if (cells[7] !== 'mined') { rowOk = false; why.push(`${id}:status`); }
125	      if (!String(cells[10] || '').includes(ENTRY)) { rowOk = false; why.push(`${id}:used-by`); }
126	      if (row.includes('\\|')) { rowOk = false; why.push(`${id}:escaped-pipe`); }
127	    }
128	    let pinOk = true;
129	    const captures = pinDoc && Array.isArray(pinDoc.captures) ? pinDoc.captures : [];
130	    for (const id of want) {
131	      const pin = captures.find((c) => c.sourceId === id);
132	      if (!pin) { pinOk = false; why.push(`${id}:unpin`); continue; }
133	      const blob = readT(pin.path);
134	      if (!blob || sha(blob) !== pin.sha256) { pinOk = false; why.push(`${id}:pin-miss`); }
135	    }
136	    hold('E3', rowOk && pinOk, why.length ? why.join(',') : 'rows+pins');
137	  }
138	  {
139	    const lesson = text('corpus/lessons/round-59.md') || '';
140	    const admit = lesson.includes('ADMIT mcp-orchestration-contract.md');
141	    const r1 = lesson.includes('REJECT durable-execution-and-fanout-primitives-2026-10-24.md');
142	    const r2 = lesson.includes('REJECT durable-execution-failure-detection.md');
143	    const flips = (lesson.match(/flip:/g) || []).length;
144	    const ok = admit && r1 && r2 && flips >= 2;
145	    hold('E4', ok, `admit=${admit} fanout=${r1} detect=${r2} flips=${flips}`);
146	  }
147	  {
148	    const col = text('.ufo/waves/round-59/assimilation/collisions');
149	    const reg = text('.ufo/waves/round-59/assimilation/reg-ids') || '';
150	    const staged = text('.ufo/waves/round-59/assimilation/staged-ids') || '';
151	    const empty = col !== null && col.split('\n').every((l) => l.trim() === '');
152	    const ok = empty && reg.includes('S124') && !reg.split('\n').includes('S125') && staged.split('\n').includes('S125');
153	    hold('E5', ok, `collisions=${col === null ? 'absent' : 'present'} empty=${empty} regS124=${reg.includes('S124')} stagedS125=${staged.split('\n').includes('S125')}`);
154	  }
155	} catch (err) {
156	  process.stderr.write(`DOCTRINE59: FAIL-CLOSED ${err && err.message}\n`);
157	  rmSync(T, { recursive: true, force: true });
158	  process.exit(2);
159	}
160	
161	const held = checks.filter((c) => c.ok).length;
162	const mismatch = checks.length !== EXPECTED_CHECKS;
163	const head = `DOCTRINE59: ${mismatch ? 'DOCTRINE59_UNMET' : (held === EXPECTED_CHECKS ? 'DOCTRINE59_HELD' : 'DOCTRINE59_UNMET')} held=${held}/${checks.length} checks=${EXPECTED_CHECKS} rev=${rev} rule=${RULE}${mismatch ? ' checks-mismatch' : ''}`;
164	finish(held === EXPECTED_CHECKS && !mismatch ? 0 : 1, head);
